"use client";

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  type SpringOptions,
  type Transition,
} from "motion/react";
import { type ComponentPropsWithoutRef, type PointerEvent, type ReactNode, useState } from "react";

import { cn } from "@/lib/utils";

/**
 * Props for a tilt card. Pass `flipped` to control which face shows, or
 * `defaultFlipped` to let the card hold its own state.
 */
export type TiltCardProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** Names the flip button. Say what the back holds, for example "Ticket details". */
  label: string;
  front: ReactNode;
  back: ReactNode;
  flipped?: boolean;
  defaultFlipped?: boolean;
  onFlippedChange?: (flipped: boolean) => void;
  /** Degrees of tilt at the card's edge. Capped at 8, so the text stays readable. */
  maxTilt?: number;
};

// Damping 33 is just over 2 × √260: critically damped, so the flip lands without rocking.
const FLIP: Transition = { type: "spring", stiffness: 260, damping: 33, mass: 1 };
// Damping 35 is just over 2 × √300, so the tilt trails the pointer and never wobbles.
const TILT: SpringOptions = { stiffness: 300, damping: 35, mass: 1 };
const TILT_CAP = 8;

const FACE = "col-start-1 row-start-1 overflow-hidden rounded-2xl border border-border bg-card text-foreground shadow-sm";

/**
 * A card with two faces. It leans a few degrees toward the pointer, and a
 * press turns it over. The flip is a real
 * toggle button, and each face is real text that is read only while it shows.
 */
export function TiltCard({
  label,
  front,
  back,
  flipped,
  defaultFlipped = false,
  onFlippedChange,
  maxTilt = 5,
  className,
  onPointerMove,
  onPointerLeave,
  ...rootProps
}: TiltCardProps) {
  const [ownFlipped, setOwnFlipped] = useState(defaultFlipped);
  const turned = flipped ?? ownFlipped;
  const reduceMotion = useReducedMotion() ?? false;
  const tilt = Math.min(Math.max(maxTilt, 0), TILT_CAP);

  const targetX = useMotionValue(0);
  const targetY = useMotionValue(0);
  const rotateX = useSpring(targetX, TILT);
  const rotateY = useSpring(targetY, TILT);

  const toggle = () => {
    if (flipped === undefined) setOwnFlipped(!turned);
    onFlippedChange?.(!turned);
  };

  const rest = () => {
    targetX.set(0);
    targetY.set(0);
  };

  const handleMove = (event: PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    // A finger has no hover, and a tilt under it would fight the press.
    if (reduceMotion || event.pointerType === "touch") return;
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0 || box.height === 0) return;
    const x = (event.clientX - box.left) / box.width;
    const y = (event.clientY - box.top) / box.height;
    // The edge nearest the pointer dips away, as if the pointer pressed on it.
    targetX.set((0.5 - y) * 2 * tilt);
    targetY.set((x - 0.5) * 2 * tilt);
  };

  return (
    <div
      {...rootProps}
      onPointerMove={handleMove}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        rest();
      }}
      className={cn("relative w-full max-w-xs perspective-distant", className)}
    >
      <motion.div style={reduceMotion ? undefined : { rotateX, rotateY }} className="relative transform-3d">
        <motion.div
          initial={false}
          animate={{ rotateY: turned && !reduceMotion ? 180 : 0 }}
          transition={FLIP}
          className="grid transform-3d"
        >
          {/* With reduced motion the faces cross-fade in place. Otherwise the turn hides the far one. */}
          <div
            aria-hidden={turned || undefined}
            className={cn(FACE, "backface-hidden", reduceMotion && "transition-opacity duration-150", reduceMotion && turned && "opacity-0")}
          >
            {front}
          </div>
          <div
            aria-hidden={!turned || undefined}
            className={cn(
              FACE,
              reduceMotion ? "transition-opacity duration-150" : "rotate-y-180 backface-hidden",
              reduceMotion && !turned && "opacity-0",
            )}
          >
            {back}
          </div>
        </motion.div>
      </motion.div>
      <button
        type="button"
        aria-label={label}
        aria-pressed={turned}
        onClick={toggle}
        // The button lies flat over the card, so its focus ring never tilts or mirrors.
        className="absolute inset-0 cursor-pointer touch-manipulation rounded-2xl outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
      />
    </div>
  );
}
